select 'bbbb0002-0000-4000-8000-000000000021', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The main job of a data engineer is to...","options":["train predictive models","build reliable systems that move and shape data for others to use","design the marketing site","manage physical servers only"],"answer":1,"explanation":"Data engineering is about dependable pipelines and storage that make data usable downstream - see ''What data engineering is''."},{"prompt":"An OLTP database (like the one behind a checkout page) is optimized for...","options":["huge analytical scans over years of history","many small, fast reads and writes of individual rows","storing images","nothing in particular"],"answer":1,"explanation":"Transactional systems handle frequent small operations; analytics is a different workload - see ''Data modeling''."},{"prompt":"In a star schema, the central table holding the measurements (like sale amount) is called the...","options":["dimension table","fact table","lookup table","staging table"],"answer":1,"explanation":"Facts hold the numeric events; dimensions describe them (who, what, when)."},{"prompt":"''Batch'' processing means...","options":["handling each event the instant it arrives","processing data in scheduled chunks, such as once per hour","deleting old data","encrypting data"],"answer":1,"explanation":"Batch groups records and runs on a schedule; streaming handles events continuously."},{"prompt":"The difference between ETL and ELT is mainly...","options":["ETL is always faster","whether you transform the data before or after loading it into the destination","ELT cannot use SQL","there is no difference"],"answer":1,"explanation":"ETL transforms before load; ELT loads raw first, then transforms inside the warehouse."},{"prompt":"A data lake differs from a data warehouse mainly because a lake...","options":["stores only clean, modeled tables","stores raw files of many shapes and sizes cheaply","cannot hold large data","requires no storage"],"answer":1,"explanation":"Lakes hold raw, varied files; warehouses hold structured, query-ready tables."},{"prompt":"An orchestration tool schedules pipeline steps as a DAG, which stands for...","options":["Data Access Grant","Directed Acyclic Graph","Distributed Array Group","Daily Automated Job"],"answer":1,"explanation":"A DAG lays out tasks and their dependencies with no cycles - see ''Orchestration''."},{"prompt":"Parquet is popular for analytics because it is...","options":["a row-based text format","a columnar binary format that compresses well and reads only needed columns","a database engine","a scheduling tool"],"answer":1,"explanation":"Columnar storage lets a query touch just the columns it needs and compress each column tightly."}]}'::jsonb, null, 10),
  (2, 'What data engineering is and the data lifecycle', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe what a data engineer does and name the stages a piece of data passes through from creation to use. Warm-up: when you click ''buy'' in an online store, where does that one row of order data need to travel before an analyst can count this month''s sales?"},{"heading":"The idea","text":"A data engineer builds and maintains the systems that move data from where it is produced to where it is consumed, keeping it correct, timely, and easy to query. The data lifecycle names the stages that data passes through: generation (an app writes an order row), ingestion (that row is copied out of the source), storage (it lands in a lake or warehouse), transformation (raw records are cleaned and reshaped into tidy tables), serving (analysts, dashboards, and reports read those tables), and finally archival or deletion. Each stage is a place where a data engineer adds reliability: retries when a copy fails, checks that no rows were lost, and clear ownership so a broken feed has someone to fix it."},{"heading":"Worked examples","text":"A retail app writes each purchase to an orders table in its transactional database. Overnight, an ingestion job copies new rows into cloud storage as files. A transformation step then loads them into a warehouse table called fct_orders, converting the amount from cents to dollars and joining the customer''s country. A dashboard reads fct_orders to show daily revenue. If the ingestion job silently skipped a file, the dashboard would undercount - so the engineer adds a check comparing the source row count to the loaded row count. That single guardrail is the difference between a number you can trust and one you cannot."},{"heading":"Your turn","text":"1) Put these lifecycle stages in order: transformation, generation, serving, ingestion, storage. 2) Which stage does a dashboard belong to? 3) Name one failure a data engineer guards against during ingestion. 4) True or false: cleaning cents into dollars is a transformation step. 5) Who consumes the data at the serving stage? Answers: 1) generation, ingestion, storage, transformation, serving. 2) serving. 3) rows lost or a file skipped (guarded by a row-count check and retries). 4) True. 5) analysts, dashboards, and reports (people and tools that read the tidy tables)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a data engineer''s job is to analyze the data - that is the analyst''s job; the engineer makes the data trustworthy and available. Mistake: skipping validation because ''the job ran without error'' - a job can succeed and still lose rows. Exit: (a) Name the six lifecycle stages in order. (b) What single check catches rows lost during ingestion? Answers: generation, ingestion, storage, transformation, serving, archival; a row-count comparison between source and destination."}]}'::jsonb, 'Say ''a data engineer builds pipelines''; the pipeline moves data, the engineer builds the pipeline - keep the actor and the artifact distinct.', 12),
  (3, 'Data modeling: OLTP vs OLAP and the star schema', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell an OLTP workload from an OLAP one and design a simple star schema with one fact table and a few dimension tables. Warm-up: would you rather store ''this one order, right now'' or ''all orders from the last three years'' in the same table shape? Why might those want different designs?"},{"heading":"The idea","text":"OLTP (online transaction processing) is the workload behind live applications: many small reads and writes of individual rows, kept highly normalized to avoid duplication. OLAP (online analytical processing) is the workload behind reporting: large scans that sum and group millions of rows, where a bit of duplication is fine if it makes queries simpler and faster. Analytics data is often modeled as a star schema: a central fact table of measurable events (each row a sale, with keys and numbers) surrounded by dimension tables that describe those events (dim_customer, dim_product, dim_date). The fact table stays narrow and long; dimensions stay short and wide. Queries join the fact to a few dimensions and group by descriptive columns."},{"heading":"Worked examples","text":"A star schema for sales:\nfct_sales(sale_id, date_key, product_key, customer_key, quantity, amount)\ndim_date(date_key, day, month, year, weekday)\ndim_product(product_key, name, category)\ndim_customer(customer_key, name, country)\nRevenue by month and category is then a clean join:\nselect d.month, p.category, sum(f.amount) as revenue\nfrom fct_sales f\njoin dim_date d on d.date_key = f.date_key\njoin dim_product p on p.product_key = f.product_key\ngroup by d.month, p.category\norder by d.month, revenue desc;\nThe fact table holds only keys and numbers; the human-readable labels live in the dimensions."},{"heading":"Your turn","text":"1) Is a checkout page''s write of one order OLTP or OLAP? 2) Is a query summing three years of revenue OLTP or OLAP? 3) In the schema above, which table would ''category'' live in? 4) Which column in fct_sales would you sum for revenue? 5) You want revenue by country - which dimension must you join? Answers: 1) OLTP. 2) OLAP. 3) dim_product. 4) amount. 5) dim_customer (it holds country)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: putting descriptive text like product name directly in the fact table, which bloats it and repeats the same string millions of times - keep it in a dimension and reference it by key. Mistake: forcing OLAP scans onto the live transactional database and slowing the app; give analytics its own store. Exit: (a) What lives in a fact table versus a dimension table? (b) Name the two workloads OLTP and OLAP describe. Answers: facts hold keys and numeric measurements, dimensions hold descriptive labels; OLTP is transactional (small live reads/writes), OLAP is analytical (large scans)."}]}'::jsonb, 'A fact table holds measurements (verbs and numbers: sold, 42.00); a dimension table holds descriptions (nouns: customer, product, date). When unsure which a column belongs to, ask ''is this a number I would sum, or a label I would group by?''', 14),
  (4, 'Batch versus streaming', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Choose between batch and streaming processing for a given use case and explain the latency trade-off. Warm-up: a fraud alert must fire within seconds, but a monthly finance report can wait until midnight. Should those two use the same processing style?"},{"heading":"The idea","text":"Batch processing collects records into groups and runs on a schedule - every hour, every night - so results arrive with some delay but the system is simple and cheap. Streaming processing handles each event moments after it arrives, giving very low latency at the cost of more moving parts. The key dial is latency, the time between an event happening and its result being available. Batch trades higher latency for simplicity and easy reprocessing; streaming trades complexity for freshness. Many real systems are hybrids: a fast streaming path for alerts and a nightly batch path that recomputes the authoritative numbers. Choose by asking how fresh the answer must be and how much operational complexity you can support."},{"heading":"Worked examples","text":"Nightly batch: a scheduled job at 02:00 reads yesterday''s order files and rebuilds the revenue tables. A query captures exactly one day:\nselect count(*) from raw_orders\nwhere order_ts >= date ''2026-07-21''\n  and order_ts <  date ''2026-07-22'';\nStreaming: card swipes flow through a continuous processor that scores each transaction as it lands and emits an alert within two seconds if the score is high. The batch job values simplicity and can be rerun for a whole day if something breaks; the streaming job values freshness and must handle events that arrive slightly out of order."},{"heading":"Your turn","text":"1) A dashboard refreshed once a day - batch or streaming? 2) A fraud alert needed in seconds - batch or streaming? 3) Which style generally has lower latency? 4) Which style is usually simpler to operate and reprocess? 5) Name the metric that measures ''time from event to result.'' Answers: 1) batch. 2) streaming. 3) streaming. 4) batch. 5) latency."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reaching for streaming when a nightly batch would do - the extra complexity is not free and often is not needed. Mistake: confusing latency (delay per event) with throughput (volume per unit time); a batch job can have huge throughput yet high latency. Exit: (a) Which style gives lower latency? (b) Which is easier to reprocess for a full day? Answers: streaming; batch."}]}'::jsonb, '''Latency'' is how long data takes to become available; ''throughput'' is how much data you move per unit time. Low latency and high throughput are different goals and sometimes trade off against each other.', 12),
  (5, 'ETL, ELT, and pipelines', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain the Extract-Transform-Load steps, contrast ETL with ELT, and sketch a small pipeline as a sequence of stages. Warm-up: if your destination warehouse is powerful and cheap to compute in, does it still make sense to transform the data on a separate machine before loading it?"},{"heading":"The idea","text":"A pipeline is an ordered sequence of stages that carry data from a source to a usable form. The three classic verbs are Extract (pull data out of a source), Transform (clean, reshape, and enrich it), and Load (write it to the destination). ETL transforms the data on the way in, before it lands in the warehouse - useful when the destination is expensive to compute in or when data must be scrubbed before storage. ELT loads the raw data first and then transforms it inside the warehouse using SQL - the common modern choice, because cloud warehouses are cheap and fast at set-based transformations and keeping the raw copy lets you rebuild tables when logic changes. Either way, each stage should be idempotent: rerunning it produces the same result rather than duplicating rows."},{"heading":"Worked examples","text":"ELT in practice. Extract lands raw JSON-like rows in a staging table raw_orders. A transform step then builds a clean table with SQL:\ncreate table stg_orders as\nselect\n  cast(id as bigint)            as order_id,\n  cast(ts as timestamp)         as order_ts,\n  amount_cents / 100.0          as amount,\n  lower(trim(country))          as country\nfrom raw_orders\nwhere id is not null;\nBecause the raw table is untouched, changing the rule (say, a new country spelling) means rerunning this one query, not re-extracting from the source. To make loads idempotent, a pipeline often deletes the target day before inserting it:\ndelete from stg_orders where order_ts::date = date ''2026-07-21'';\ninsert into stg_orders select ... ;\nRerunning the day now replaces rather than duplicates."},{"heading":"Your turn","text":"1) Spell out what E, T, and L stand for. 2) In ELT, where does the transform happen? 3) Why keep the raw extracted data around? 4) What does ''idempotent'' mean for a pipeline step? 5) Name one reason to prefer ETL (transform before load). Answers: 1) Extract, Transform, Load. 2) inside the destination warehouse, in SQL. 3) so you can rebuild transformed tables when logic changes, without re-extracting. 4) rerunning it gives the same result instead of duplicating data. 5) the destination is expensive to compute in, or data must be scrubbed or masked before it is stored."},{"heading":"Common mistakes & exit ticket","text":"Mistake: a load step that only inserts, so every rerun doubles the rows - make it delete-then-insert or use an upsert so it is idempotent. Mistake: throwing away the raw extract, which forces a slow re-pull from the source whenever a transform rule changes. Exit: (a) What is the difference between ETL and ELT? (b) Why does idempotency matter? Answers: ETL transforms before loading, ELT loads raw then transforms in the warehouse; idempotency lets you safely rerun a step without creating duplicates."}]}'::jsonb, 'The three verbs are Extract, Transform, Load. ETL transforms before loading; ELT loads first, then transforms in place. The letters name the order of operations, nothing more.', 14),
  (6, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Which stage of the data lifecycle does a revenue dashboard belong to?","options":["ingestion","storage","serving","generation"],"answer":2,"explanation":"Dashboards read the tidy tables at the serving stage."},{"prompt":"In a star schema, the product''s category label belongs in...","options":["the fact table","a dimension table","the staging file","the orchestration DAG"],"answer":1,"explanation":"Descriptive labels live in dimensions; the fact table holds keys and numbers."},{"prompt":"A checkout page writing a single order row is which workload?","options":["OLAP","OLTP","batch analytics","archival"],"answer":1,"explanation":"Small, fast, single-row writes are transactional (OLTP)."},{"prompt":"A fraud alert that must fire within seconds is best served by...","options":["nightly batch","streaming","a monthly report","manual review only"],"answer":1,"explanation":"Streaming gives the low latency such alerts require."},{"prompt":"In ELT, the transformation step runs...","options":["before loading, on a separate machine","inside the destination warehouse after loading raw data","only on the source database","never"],"answer":1,"explanation":"ELT loads raw first, then transforms in the warehouse with SQL."},{"prompt":"A load step that only inserts (never replaces) will, on each rerun...","options":["stay correct","duplicate the rows","delete the table","speed up"],"answer":1,"explanation":"Without delete-then-insert or upsert, rerunning duplicates data - it is not idempotent."}]}'::jsonb, null, 8),
  (7, 'Data warehouses, data lakes, and the lakehouse', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Contrast a data warehouse, a data lake, and a lakehouse, and say which fits a given need. Warm-up: you have millions of raw log files of varying shapes plus a set of clean, well-defined revenue tables. Would you store both the same way?"},{"heading":"The idea","text":"A data warehouse stores structured, query-ready tables with defined columns and types; it is optimized for fast SQL analytics and enforces schema on write, meaning data must fit the table shape as it is loaded. A data lake stores raw files of any shape - logs, exports, images - cheaply in object storage, applying schema on read, meaning you decide the structure only when you query. Lakes are flexible and inexpensive but can become disorganized ''swamps'' without discipline. A lakehouse is a newer pattern that puts a table layer with schema, transactions, and reliability guarantees on top of the cheap files in a lake, aiming to give warehouse-like management with lake-like cost and flexibility. A common architecture uses the lake for raw landing and the warehouse (or lakehouse tables) for the modeled, trusted layer."},{"heading":"Worked examples","text":"Raw event logs land in the lake as files organized by date:\ns3://company-lake/raw/events/date=2026-07-21/part-0001.parquet\nAn ELT job reads those files and builds a clean warehouse table analytics.fct_events with typed columns. Analysts query the warehouse table, which is fast and well-defined; engineers can still go back to the raw lake files to rebuild the table if a parsing rule changes. Schema on read versus schema on write shows up plainly here: the lake accepted the file no matter its exact shape, while the warehouse table refused any row that did not match its column types - catching bad data at load time."},{"heading":"Your turn","text":"1) Which stores raw files of any shape cheaply - lake or warehouse? 2) Which enforces schema on write? 3) What problem does a neglected lake risk becoming? 4) What does a lakehouse add on top of lake files? 5) Where would you land raw logs before modeling them? Answers: 1) lake. 2) warehouse. 3) a disorganized ''data swamp.'' 4) a table layer with schema, transactions, and reliability guarantees. 5) the data lake."},{"heading":"Common mistakes & exit ticket","text":"Mistake: dumping everything into a lake with no naming or catalog, creating a swamp nobody can query. Mistake: assuming a warehouse can cheaply hold every raw file forever - raw, high-volume, oddly-shaped data usually belongs in the lake first. Exit: (a) Which applies schema on read, the lake or the warehouse? (b) What is the one-line pitch of a lakehouse? Answers: the lake reads schema at query time (the warehouse writes it at load time); a lakehouse adds warehouse-style structure and guarantees on top of cheap lake files."}]}'::jsonb, 'A warehouse stores structured tables; a lake stores raw files; a lakehouse adds table-like structure and guarantees on top of files in a lake. Match the noun to what it primarily stores.', 13),
  (8, 'Orchestration: DAGs and scheduling', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Model a pipeline as a DAG of tasks with dependencies and explain how a scheduler runs and retries it. Warm-up: your transform step must not run until the extract finishes, and the dashboard refresh must not run until the transform finishes. How would you write down those ''must happen after'' rules?"},{"heading":"The idea","text":"Orchestration is the coordination of a pipeline''s tasks: deciding what runs, in what order, and what happens when something fails. Tasks and their dependencies form a DAG - a Directed Acyclic Graph - where an edge from A to B means ''A must finish before B starts.'' Acyclic means the dependencies never loop, so there is always a valid order to run them. A scheduler triggers the DAG on a schedule (say daily at 02:00), runs tasks whose upstream dependencies have all succeeded, and on failure can retry a task a few times before marking it failed and alerting a human. Because a good DAG''s tasks are idempotent, a failed run can simply be re-executed. Orchestration turns a pile of scripts into a dependable, observable system."},{"heading":"Worked examples","text":"A daily DAG has four tasks with these dependencies:\nextract_orders -> transform_orders -> load_warehouse -> refresh_dashboard\nThe arrows are the edges: transform_orders will not start until extract_orders succeeds, and refresh_dashboard waits for load_warehouse. If transform_orders fails, the scheduler retries it (say up to three times, waiting a minute between tries); if it still fails, load_warehouse and refresh_dashboard are skipped and an alert fires - so the dashboard never shows half-loaded data. A branch is possible too: after load_warehouse, both refresh_dashboard and send_summary_email can run in parallel because neither depends on the other."},{"heading":"Your turn","text":"1) What do the letters D, A, G stand for? 2) In extract -> transform -> load, which task is upstream of load? 3) Why must the graph be acyclic? 4) What does a scheduler typically do when a task fails? 5) Can two tasks run in parallel if neither depends on the other? Answers: 1) Directed, Acyclic, Graph. 2) transform (and extract before it). 3) so a valid run order always exists - a cycle would mean a task depends on itself. 4) retry it a set number of times, then alert and skip downstream tasks. 5) yes."},{"heading":"Common mistakes & exit ticket","text":"Mistake: writing tasks that are not idempotent, so a retry double-loads data instead of safely repeating. Mistake: creating a hidden cycle (task A waits on B while B waits on A), which can never run - keep the graph acyclic. Exit: (a) What does an edge from A to B mean in a pipeline DAG? (b) What is one thing a scheduler does on failure? Answers: A must finish successfully before B starts; it retries the task and, if it still fails, alerts and skips downstream tasks."}]}'::jsonb, 'A DAG is Directed (tasks point to what comes next), Acyclic (no loops back), and a Graph (nodes and edges). ''Upstream'' means a task another depends on; ''downstream'' means a task that depends on it.', 13),
  (9, 'Data quality and validation', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the common dimensions of data quality and write simple validation checks that fail loudly when data is wrong. Warm-up: a pipeline ran without any error, yet the revenue number looks doubled. What kinds of silent problems could cause that?"},{"heading":"The idea","text":"Data quality is whether the data is fit to trust. Common dimensions are completeness (no missing rows or values that should be present), uniqueness (no unintended duplicates), validity (values fall in allowed ranges or formats), consistency (numbers agree across tables), and timeliness (the data is fresh enough). A validation check is an assertion the data must satisfy; if it fails, the pipeline should stop or quarantine the bad rows rather than publish them. The goal is to fail loudly and early, near the source of the problem, instead of letting a wrong number reach a dashboard where it is trusted. Tests run as part of the pipeline, right after a transform, so a bad load never becomes the serving layer."},{"heading":"Worked examples","text":"Uniqueness - order_id must be unique:\nselect order_id, count(*) as n\nfrom stg_orders\ngroup by order_id\nhaving count(*) > 1;\nAny returned rows are duplicates; the pipeline treats a non-empty result as a failure. Completeness - no null keys:\nselect count(*) as null_ids from stg_orders where order_id is null;\nValidity - amounts must be non-negative:\nselect count(*) as bad_amounts from stg_orders where amount < 0;\nEach check should return zero. Wiring them in means the DAG runs these queries after the transform and refuses to load the warehouse if any count is greater than zero - catching the doubled-revenue bug (a duplicate load) before an analyst ever sees it."},{"heading":"Your turn","text":"1) Which quality dimension does ''no duplicate order_id'' test? 2) Which dimension does ''amount is never negative'' test? 3) A validity check like the ones above should return what count to pass? 4) Where in the DAG should tests run - before or after the transform? 5) Name the quality dimension about data being fresh enough. Answers: 1) uniqueness. 2) validity. 3) zero. 4) after the transform, before serving. 5) timeliness."},{"heading":"Common mistakes & exit ticket","text":"Mistake: trusting that ''the job succeeded'' means the data is correct - a job can run cleanly and still load duplicates or nulls. Mistake: logging a warning but publishing the bad data anyway; a failed critical check should block the load. Exit: (a) Name three data-quality dimensions. (b) What count should a passing validity check return? Answers: any three of completeness, uniqueness, validity, consistency, timeliness; zero."}]}'::jsonb, 'A data ''test'' asserts something that must be true (no nulls in order_id); a ''check'' is the act of running that assertion. Frame tests as claims the data must satisfy, not as steps that transform it.', 13),
  (10, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"A data lake primarily stores...","options":["clean modeled tables only","raw files of many shapes, cheaply","nothing","dashboards"],"answer":1,"explanation":"Lakes hold raw, varied files in cheap object storage."},{"prompt":"''Schema on read'' is a property of a...","options":["data warehouse","data lake","star schema","scheduler"],"answer":1,"explanation":"A lake applies structure at query time; a warehouse enforces schema on write."},{"prompt":"In a DAG, an edge from extract to transform means...","options":["they run at the same time","transform must finish before extract","extract must finish before transform starts","they are unrelated"],"answer":2,"explanation":"The arrow encodes ''the upstream task must succeed first.''"},{"prompt":"When a task fails, a typical scheduler will first...","options":["delete the pipeline","retry it a few times before alerting","publish partial data","ignore it forever"],"answer":1,"explanation":"Retries handle transient failures; persistent failure then alerts and skips downstream tasks."},{"prompt":"A uniqueness check on order_id passes when the duplicate query returns...","options":["one row","zero rows","any rows","a null"],"answer":1,"explanation":"No duplicate groups means the grouped-having query returns zero rows."},{"prompt":"A lakehouse aims to combine...","options":["two warehouses","lake-like cost and flexibility with warehouse-like structure and guarantees","streaming and batch","OLTP and archival"],"answer":1,"explanation":"It adds a managed table layer on top of cheap lake files."}]}'::jsonb, null, 8),
  (11, 'Partitioning and file formats: Parquet and columnar storage', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why columnar formats like Parquet speed up analytics and how partitioning lets a query skip data it does not need. Warm-up: a report only ever sums the amount column across one month, yet a CSV scan reads every column of every row for all time. Where is the waste?"},{"heading":"The idea","text":"A file format decides how bytes are laid out on disk. Row-based formats such as CSV store all fields of one record together, which is fine for writing whole rows but wasteful for analytics that touch only a few columns. Columnar formats such as Parquet store each column''s values together, so a query that needs only amount reads just that column and skips the rest; because values in a column are similar, they also compress far better. Partitioning is a complementary idea: split the data into separate folders by a key such as date, so a query filtered to one day can read only that day''s folder and prune the rest. Together, columnar storage plus partitioning mean a query reads a tiny slice of the data instead of all of it - often the single biggest speed and cost win in a warehouse."},{"heading":"Worked examples","text":"Partitioned Parquet on disk, split by day:\nlake/events/date=2026-07-20/part-000.parquet\nlake/events/date=2026-07-21/part-000.parquet\nA query filtered to one day only opens that day''s folder:\nselect sum(amount) from events where date = ''2026-07-21'';\nThe engine prunes every other date partition (never reading them) and, thanks to columnar layout, reads only the amount column within the chosen files. Compare the costs: a single CSV of all events forces a full scan of every column and every day; the partitioned columnar layout touches one day and one column. Same answer, a fraction of the bytes read."},{"heading":"Your turn","text":"1) Does Parquet store data by row or by column? 2) Why does columnar layout compress well? 3) If data is partitioned by date, what can a one-day query skip? 4) Which is better for a query summing a single column over billions of rows - CSV or Parquet? 5) Is partitioning about the file format or the folder layout? Answers: 1) by column. 2) values within a column are similar, so they compress tightly. 3) every partition (folder) except the requested date. 4) Parquet. 5) the folder layout (how data is split), independent of the format."},{"heading":"Common mistakes & exit ticket","text":"Mistake: partitioning by a very high-cardinality key like user_id, creating millions of tiny files that slow everything down - partition by something coarse such as date. Mistake: assuming CSV is always fine because it is human-readable; for large analytics it reads far more bytes than a columnar format. Exit: (a) Why does a columnar format speed up a query that needs one column? (b) What does partitioning by date let a single-day query avoid? Answers: it reads only that column instead of every column; it lets the query skip every other date''s folder."}]}'::jsonb, '''Row-based'' formats (CSV) store one record''s fields together; ''columnar'' formats (Parquet) store one column''s values together. Partitioning splits data into folders by a key; it is about layout, not format.', 13),
  (12, 'The modern data stack, end to end', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Sketch how the pieces you have learned fit into one end-to-end stack and place a new tool into the right layer. Warm-up: you have met ingestion, storage, modeling, orchestration, and quality checks separately. Can you draw the arrow from a raw click all the way to a chart?"},{"heading":"The idea","text":"The modern data stack is the set of layers that together carry data from sources to decisions. Ingestion pulls data from sources (apps, files, third-party systems) into central storage. Storage is the lake and warehouse (or lakehouse) that hold raw and modeled data. Transformation, usually ELT in SQL, turns raw tables into clean, well-modeled ones like fct_sales. Orchestration schedules and connects all these steps as a DAG and retries failures. Data quality checks guard the modeled layer so only trustworthy tables are served. Serving exposes the results to dashboards, reports, and downstream systems. No single product is ''the stack'' - the value is in the layers cooperating, each doing one job well, with clear ownership and monitoring across them."},{"heading":"Worked examples","text":"Trace one click through the stack. A user buys something (generation). An ingestion job copies the order into the lake as partitioned Parquet (ingestion + storage). A scheduled DAG runs an ELT transform that builds fct_sales in the warehouse (orchestration + transformation), then runs uniqueness and validity checks (quality). Only if the checks pass does the DAG refresh the revenue dashboard (serving). Map each earlier lesson to a layer: star schema -> transformation and storage; batch versus streaming -> ingestion; DAGs -> orchestration; Parquet and partitioning -> storage. The whole course is one picture: the layers of a working stack."},{"heading":"Your turn","text":"1) Which layer does a scheduling DAG belong to? 2) Which layer holds raw and modeled data? 3) In which layer does the ELT SQL that builds fct_sales run? 4) Which layer exposes results to a dashboard? 5) True or false: the modern data stack is a single product you buy. Answers: 1) orchestration. 2) storage. 3) transformation. 4) serving. 5) False - it is cooperating layers, each with its own tools."},{"heading":"Common mistakes & exit ticket","text":"Mistake: chasing tools before understanding the layers - a new product only helps if you know which job it does. Mistake: treating quality checks as optional bolt-ons rather than a gate before serving. Exit: (a) Name the layers of the stack in order from source to dashboard. (b) Which layer is the last gate before serving? Answers: ingestion, storage, transformation, orchestration (tying them together), quality, serving; the data-quality checks are the last gate before serving."}]}'::jsonb, 'Name each layer by its job: ingestion moves data in, storage holds it, transformation models it, orchestration schedules it, serving exposes it. A ''stack'' is these layers working together, not a single tool.', 12),
  (13, 'Capstone: build a small end-to-end pipeline', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Assemble a complete daily pipeline for a shop''s orders - extract, model into a star schema, validate, and serve - using every idea in this course. Warm-up: before writing any code, list the stages your pipeline needs and the order they must run in."},{"heading":"The idea","text":"You will build a daily batch pipeline, run by a scheduler as a DAG, for a store''s orders. The design ties the whole course together: ingest raw orders into the lake as partitioned Parquet; run an idempotent ELT transform that builds a star schema (fct_sales plus dim_date, dim_product, dim_customer) in the warehouse; run data-quality checks; and only on success refresh a revenue dashboard. Each stage is idempotent, so rerunning any day replaces rather than duplicates. The point is not any single query but the shape of a reliable system: clear stages, explicit dependencies, validation before serving, and the ability to rerun safely when something fails."},{"heading":"Worked examples","text":"The DAG:\nextract_orders -> build_star -> quality_checks -> refresh_dashboard\nStage 2, an idempotent transform for one day (delete-then-insert):\ndelete from fct_sales where date_key = 20260721;\ninsert into fct_sales (sale_id, date_key, product_key, customer_key, quantity, amount)\nselect o.order_id, 20260721, o.product_key, o.customer_key, o.quantity,\n       o.amount_cents / 100.0\nfrom stg_orders o\nwhere o.order_ts >= date ''2026-07-21''\n  and o.order_ts <  date ''2026-07-22'';\nStage 3, the quality gate (each must return zero):\nselect count(*) from fct_sales\n where date_key = 20260721 group by sale_id having count(*) > 1;  -- duplicates\nselect count(*) from fct_sales where amount < 0;                  -- invalid amounts\nIf either check fails, the scheduler stops before refresh_dashboard, so a bad day never reaches the report. Rerun tomorrow''s failure and the delete-then-insert makes it clean."},{"heading":"Your turn","text":"1) List the four DAG stages in order. 2) What makes the build_star stage idempotent? 3) Why do the quality checks run before refresh_dashboard? 4) Which format and partition layout land the raw orders? 5) Name the fact table and one dimension in the star schema. Answers: 1) extract_orders, build_star, quality_checks, refresh_dashboard. 2) it deletes the day before inserting it, so a rerun replaces rather than duplicates. 3) so a failed check blocks serving and a bad day never reaches the dashboard. 4) Parquet, partitioned by date. 5) fct_sales, with any of dim_date, dim_product, or dim_customer."},{"heading":"Common mistakes & exit ticket","text":"Mistake: an insert-only build stage that doubles a day''s rows on every rerun - always delete-then-insert or upsert. Mistake: refreshing the dashboard even when a quality check failed, publishing wrong numbers. Exit: (a) In one sentence, what are the four stages of this pipeline? (b) What single change makes the transform safe to rerun? Answers: extract the orders, build the star schema, run quality checks, then refresh the dashboard; deleting the target day before inserting it (delete-then-insert) so reruns replace instead of duplicate."}]}'::jsonb, 'Describe the pipeline as stages with dependencies (extract, then transform, then test, then load), and make every stage idempotent so the whole thing can be rerun for a day without harm.', 16),
  (14, 'Comprehensive final quiz', 'quiz', '{"questions":[{"prompt":"Put the data lifecycle in order:","options":["serving, storage, ingestion, generation","generation, ingestion, storage, transformation, serving","ingestion, generation, serving, storage","transformation, serving, ingestion, storage"],"answer":1,"explanation":"Data is generated, ingested, stored, transformed, then served (before eventual archival)."},{"prompt":"A narrow-and-long table of sale events with keys and numbers is the star schema''s...","options":["dimension table","fact table","staging file","lake"],"answer":1,"explanation":"The fact table holds the measurable events; dimensions describe them."},{"prompt":"Which workload is optimized for large scans that sum millions of rows?","options":["OLTP","OLAP","checkout writes","single-row lookups"],"answer":1,"explanation":"OLAP is the analytical workload; OLTP handles small live transactions."},{"prompt":"Compared with batch, streaming offers...","options":["higher latency","lower latency","simpler reprocessing","no need for schedulers"],"answer":1,"explanation":"Streaming processes events as they arrive, giving lower latency."},{"prompt":"In ELT, transformations happen...","options":["before loading, off to the side","after loading, inside the warehouse in SQL","only in the source app","never"],"answer":1,"explanation":"ELT loads raw data first, then transforms it in the destination."},{"prompt":"''Schema on read'' describes a...","options":["warehouse","data lake","fact table","DAG"],"answer":1,"explanation":"The lake applies structure at query time; the warehouse enforces it at load time."},{"prompt":"In a pipeline DAG, an edge from A to B means...","options":["B runs before A","A must finish before B starts","A and B are unrelated","A depends on B"],"answer":1,"explanation":"The directed edge encodes the upstream-before-downstream dependency."},{"prompt":"A validity check such as ''amount is never negative'' passes when it returns a count of...","options":["one","zero","any positive number","null"],"answer":1,"explanation":"Zero offending rows means the assertion holds."},{"prompt":"Parquet speeds up analytics chiefly because it is...","options":["row-based and uncompressed","columnar and well-compressed, reading only needed columns","a scheduler","a warehouse engine"],"answer":1,"explanation":"Columnar storage reads just the required columns and compresses each column tightly."},{"prompt":"Partitioning a table by date lets a single-day query...","options":["read every partition","skip every other date''s folder","ignore the filter","rewrite the schema"],"answer":1,"explanation":"Partition pruning reads only the requested day''s folder."},{"prompt":"The single change that makes a daily load safe to rerun is...","options":["insert-only every time","delete-then-insert (or upsert) the target day","dropping the table nightly","disabling checks"],"answer":1,"explanation":"Replacing the day rather than appending keeps the step idempotent."},{"prompt":"In the modern data stack, the last gate before serving should be...","options":["ingestion","the data-quality checks","generation","archival"],"answer":1,"explanation":"Quality checks guard the modeled layer so only trustworthy tables are served."}]}'::jsonb, null, 12)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-000000000021' and l.position = v.pos
);
